QUIZ_DATABASE["N3"]["dochieu"] = {"label": "Đọc Hiểu", "unitLabel": "unit", "slots": 15, "tests": {"1": {"title": "Unit 01 · 名詞 A — Danh từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "最近（さいきん）、私（わたし）は 朝（あさ）５時（じ）に 起（お）きるように なった。若（わか）い うちに、いろいろな 経験（けいけん）を しておきたいからだ。散歩（さんぽ）の 最中（さいちゅう）に、近所（きんじょ）の 人（ひと）と 話（はな）すことも 増（ふ）えた。", "questions": [{"q": "Vì sao người viết bắt đầu dậy lúc 5 giờ?", "options": ["Vì phải đưa con đi học", "Muốn tích lũy nhiều kinh nghiệm khi còn trẻ", "Vì công việc đổi ca", "Vì không ngủ được"], "answer": 1, "explain": "「若いうちに、いろいろな経験をしておきたいからだ」 — ～うちに Bài ngữ pháp Unit 01."}, {"q": "Người viết thường nói chuyện với hàng xóm vào lúc nào?", "options": ["Trong lúc đi làm", "Vào buổi tối", "Trong lúc ăn sáng", "Trong lúc đi dạo"], "answer": 3, "explain": "「散歩の最中に」 = đúng lúc đang đi dạo."}, {"q": "Thói quen mới của người viết là gì?", "options": ["Dậy lúc 5 giờ sáng", "Chạy bộ buổi tối", "Học bài khuya", "Ngủ trưa mỗi ngày"], "answer": 0, "explain": "Câu đầu: 「朝５時に起きるようになった」."}, {"q": "Theo đoạn văn, dậy sớm mang lại điều gì?", "options": ["Không phải đi làm", "Có nhiều thời gian ngủ hơn", "Có cơ hội trò chuyện với hàng xóm nhiều hơn", "Được tăng lương"], "answer": 2, "explain": "「近所の人と話すことも増えた」 — nói chuyện với hàng xóm cũng tăng lên."}]}, "2": {"title": "Unit 02 · 動詞 A — Động từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "日本（にほん）の 人口（じんこう）は 減（へ）りつつある。特（とく）に 若（わか）い 人（ひと）の 数（かず）は 年々（ねんねん）少（すく）なく なって いる。政府（せいふ）は 対策（たいさく）を 考（かんが）えつつも、まだ 決定的（けっていてき）な 方法（ほうほう）は 見（み）つかって いない。", "questions": [{"q": "Dân số Nhật Bản đang thay đổi thế nào?", "options": ["Đang dần giảm", "Tăng giảm thất thường", "Không thay đổi", "Đang tăng nhanh"], "answer": 0, "explain": "「人口は減りつつある」 — ～つつある chỉ biến đổi đang tiến triển."}, {"q": "Đối tượng giảm rõ nhất là gì?", "options": ["Số công nhân", "Số người trẻ", "Số người già", "Số trẻ em nước ngoài"], "answer": 1, "explain": "「特に若い人の数は年々少なくなっている」."}, {"q": "Chính phủ đã tìm ra giải pháp quyết định chưa?", "options": ["Không cần giải pháp", "Chưa", "Đã tìm ra", "Đang thử nghiệm thành công"], "answer": 1, "explain": "「まだ決定的な方法は見つかっていない」."}, {"q": "Mẫu ～つつも trong câu cuối có nghĩa là gì?", "options": ["Đang dần dần", "Mặc dù đang (suy nghĩ) nhưng...", "Trong khi đang (đi)", "Vừa...vừa... (đồng thời đơn thuần)"], "answer": 1, "explain": "政府は対策を考えつつも = dù đang cân nhắc đối sách nhưng (vẫn chưa có cách) — nhượng bộ văn viết."}]}, "3": {"title": "Tổng hợp 1 · 連用名詞 — Danh từ liên động từ — Đọc hiểu · Mimi kara Oboeru", "passage": "電車（でんしゃ）が 大雪（おおゆき）で 止（と）まって しまった。会社（かいしゃ）まで 歩（ある）いて 行（い）く ざるを 得（え）ない。２時間（じかん）も かかったが、約束（やくそく）の 時間（じかん）には どうにか 間（ま）に 合（あ）った。", "questions": [{"q": "Vì sao người viết phải đi bộ đến công ty?", "options": ["Đường bị cấm xe", "Xe buýt hết chuyến", "Tàu dừng vì tuyết lớn", "Muốn tập thể dục"], "answer": 2, "explain": "「電車が大雪で止まってしまった」 nên 「歩いて行くざるを得ない」."}, {"q": "Đi bộ mất bao lâu?", "options": ["1 tiếng", "2 tiếng", "30 phút", "3 tiếng"], "answer": 1, "explain": "「２時間もかかった」."}, {"q": "Cuối cùng người viết có kịp giờ hẹn không?", "options": ["Họp dời sang mai", "Không, trễ 1 tiếng", "Có, vừa kịp", "Hủy cuộc hẹn"], "answer": 2, "explain": "「どうにか間に合った」 = cuối cùng cũng kịp."}, {"q": "Mẫu ～ざるを得ない diễn tả điều gì?", "options": ["Buộc phải làm vì không còn lựa chọn", "Được phép làm", "Rất muốn làm", "Có thể làm dễ dàng"], "answer": 0, "explain": "雪で電車が止まった状況で 歩くざるを得ない = không còn cách nào khác ngoài đi bộ."}]}, "4": {"title": "Unit 03 · 形容詞 A — Tính từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "この 仕事（しごと）は 思（おも）った ほど 難（むずか）しくは なかった。練習（れんしゅう）すれば する ほど、自信（じしん）も ついて くる。疲（つか）れた 日（ひ）は、死（し）ぬ ほど 眠（ねむ）い ことも あるが、やりがいが ある。", "questions": [{"q": "Công việc thực tế so với tưởng tượng thế nào?", "options": ["Không khó đến mức tưởng", "Khó đúng như tưởng", "Dễ đến mức nhàm chán", "Khó hơn nhiều"], "answer": 0, "explain": "「思ったほど難しくはなかった」 — ～ほど～ない."}, {"q": "Điều gì tăng theo luyện tập?", "options": ["Mệt mỏi", "Áp lực", "Sự tự tin", "Thời gian làm việc"], "answer": 2, "explain": "「練習すればするほど、自信もついてくる」 — ～ば～ほど."}, {"q": "Câu 「死ぬほど眠い」 có nghĩa đen là gì?", "options": ["Ngủ say như chết thật", "Ngủ quên cả ngày", "Buồn ngủ đến mức cực độ (ví von)", "Mất ngủ hoàn toàn"], "answer": 2, "explain": "～ほど ở đây là ví von mức độ cực đoan: buồn ngủ 'đến chết được'."}, {"q": "Người viết cảm thấy công việc thế nào?", "options": ["Không muốn tiếp tục", "Có ý nghĩa / đáng làm (やりがい)", "Chỉ làm vì tiền", "Quá nhàm chán"], "answer": 1, "explain": "Câu cuối: 「やりがいがある」 = công việc có giá trị, đáng bỏ công."}]}, "5": {"title": "Tổng hợp 2 · 形容詞＋まる/める — Tính từ + まる/める — Đọc hiểu · Mimi kara Oboeru", "passage": "兄（あに）は 約束（やくそく）を 忘（わす）れがちだ。最近（さいきん）、私（わたし）も 少（すこ）し 疲（つか）れぎみで、物忘（ものわす）れが 多（おお）い。あの 子（こ）は 大人（おとな）っぽい 話（はな）し方（かた）を するので、初（はじ）めは 驚（おどろ）いた。", "questions": [{"q": "Anh trai có xu hướng gì?", "options": ["Hay nói dối", "Hay đến muộn", "Hay quên lời hứa", "Hay quên đồ"], "answer": 2, "explain": "「約束を忘れがちだ」 — ～がち = hay có xu hướng (tiêu cực)."}, {"q": "Người viết gần đây thế nào?", "options": ["Hơi mệt và hay quên đồ", "Rất khỏe mạnh", "Mất ngủ triền miên", "Ăn không ngon"], "answer": 0, "explain": "「疲れぎみで、物忘れが多い」 — ～ぎみ = hơi có vẻ."}, {"q": "Đứa trẻ kia làm người viết ngạc nhiên vì sao?", "options": ["Nói được ba thứ tiếng", "Cách nói chuyện như người lớn", "Đọc sách rất nhanh", "Hát rất hay"], "answer": 1, "explain": "「大人っぽい話し方」 — ～っぽい = trông như/có vẻ như."}, {"q": "Ba mẫu trong đoạn 忘れがち・疲れぎみ・大人っぽい đều diễn tả điều gì?", "options": ["Điều kiện giả định", "Mệnh lệnh lịch sự", "Xu hướng / vẻ ngoài / tính chất dễ nhận thấy", "Thời gian quá khứ"], "answer": 2, "explain": "Đây là nhóm mẫu Unit này: ～がち (xu hướng), ～ぎみ (hơi có vẻ), ～っぽい (trông như)."}]}, "6": {"title": "Unit 04 · 名詞 B — Danh từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "私（わたし）は 環境問題（かんきょうもんだい）に ついて レポートを 書（か）いた。子供（こども）に とって、自然（しぜん）は 一番（いちばん）の 先生（せんせい）だ。私（わたし）たちは 次（つぎ）の 世代（せだい）に 対（たい）して 責任（せきにん）が ある。", "questions": [{"q": "Báo cáo của người viết về chủ đề gì?", "options": ["Y tế", "Giáo dục", "Kinh tế", "Vấn đề môi trường"], "answer": 3, "explain": "「環境問題についてレポートを書いた」 — ～について."}, {"q": "Đối với trẻ em, điều gì là người thầy tốt nhất?", "options": ["Cha mẹ", "Thiên nhiên", "Thầy cô", "Sách vở"], "answer": 1, "explain": "「子供にとって、自然は一番の先生だ」 — ～にとって (đối với)."}, {"q": "Chúng ta có trách nhiệm với ai?", "options": ["Bạn bè", "Chính phủ", "Thế hệ sau", "Công ty"], "answer": 2, "explain": "「次の世代に対して責任がある」 — ～に対して."}, {"q": "～にとって và ～に対して khác nhau thế nào trong đoạn?", "options": ["Cả hai hoàn toàn giống nhau", "に対して chỉ dùng cho thiên nhiên", "にとって chỉ dùng cho vật", "にとって = theo quan điểm/đối với ai đó; に対して = hướng tới đối tượng của thái độ/hành động"], "answer": 3, "explain": "子供にとって (quan điểm) khác 次の世代に対して (đối tượng của trách nhiệm)."}]}, "7": {"title": "Unit 05 · 動詞 B — Động từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "話（はな）し合（あ）いの 結果（けっか）、イベントは 中止（ちゅうし）に する ことに なった。私（わたし） 自身（じしん）は 続（つづ）ける ことに したかったが、みんなの 意見（いけん）を 尊重（そんちょう）した。今後（こんご）は 安全（あんぜん）に もっと 気（き）を つけるように したい。", "questions": [{"q": "Sự kiện cuối cùng được quyết định thế nào?", "options": ["Hoãn một tuần", "Đổi địa điểm", "Hủy bỏ", "Giảm quy mô"], "answer": 2, "explain": "「中止にすることになった」 — quyết định tập thể （ことになった)."}, {"q": "Bản thân người viết muốn thế nào?", "options": ["Muốn tiếp tục tổ chức", "Muốn hủy từ đầu", "Không có ý kiến", "Muốn giao cho người khác"], "answer": 0, "explain": "「私は続けることにしたかった」 — ý muốn cá nhân dùng ことにした."}, {"q": "Vì sao người viết chấp nhận quyết định chung?", "options": ["Bị ép buộc", "Tôn trọng ý kiến mọi người", "Không còn tiền", "Hết thời gian"], "answer": 1, "explain": "「みんなの意見を尊重した」."}, {"q": "～ことになった và ～ことにした khác nhau ở điểm nào?", "options": ["ことになった dùng cho quá khứ xa", "Cả hai đều là tự quyết", "ことにした chỉ dùng trong văn viết", "ことになった = quyết định từ bên ngoài/tập thể; ことにした = tự mình quyết định"], "answer": 3, "explain": "Đây là điểm phân biệt cốt lõi của Unit 05 ngữ pháp N3."}]}, "8": {"title": "Unit 06 · カタカナ A — Từ mượn A — Đọc hiểu · Mimi kara Oboeru", "passage": "この サービスは 年齢（ねんれい）に 応（おう）じて 料金（りょうきん）が 変（か）わる。申（もう）し込（こ）みは インターネットを 通（つう）じて 行（おこな）う。キャンペーンは ３か月（げつ）に わたって 続（つづ）く 予定（よてい）だ。", "questions": [{"q": "Giá tiền thay đổi theo yếu tố nào?", "options": ["Độ tuổi", "Thu nhập", "Địa chỉ", "Số người"], "answer": 0, "explain": "「年齢に応じて料金が変わる」 — ～に応じて = tùy theo."}, {"q": "Đăng ký được thực hiện qua đâu?", "options": ["Bưu điện", "Điện thoại", "Tại quầy", "Internet"], "answer": 3, "explain": "「インターネットを通じて行う」 — ～を通じて = thông qua."}, {"q": "Chiến dịch kéo dài bao lâu?", "options": ["1 tháng", "2 tuần", "Nửa năm", "Suốt 3 tháng"], "answer": 3, "explain": "「３か月にわたって続く」 — ～にわたって = kéo dài suốt."}, {"q": "Cụm ３か月にわたって nhấn mạnh điều gì?", "options": ["Điều kiện", "Phạm vi/khoảng thời gian trải dài", "Sự cho phép", "Nguyên nhân"], "answer": 1, "explain": "～にわたって dùng cho khoảng thời gian hoặc phạm vi rộng."}]}, "9": {"title": "Unit 07 · 形容詞 B — Tính từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "彼（かれ）は 寝（ね）て ばかり いる。冗談（じょうだん）を 言（い）った ばかりに、彼女（かのじょ）に 怒（おこ）られて しまった。今年（ことし）こそは 必（かなら）ず 目標（もくひょう）を 達成（たっせい）したい。", "questions": [{"q": "Anh ta bị nhận xét là chỉ toàn làm gì?", "options": ["Ngủ", "Ăn", "Chơi", "Xem tivi"], "answer": 0, "explain": "「寝てばかりいる」 — ～てばかりいる (chỉ toàn)."}, {"q": "Vì sao cô ấy giận?", "options": ["Vì anh ta đến muộn", "Vì anh ta quên sinh nhật", "Vì anh ta nói dối", "Chỉ vì một câu nói đùa"], "answer": 3, "explain": "「冗談を言ったばかりに」 — ～ばかりに = chỉ vì...mà (hậu quả xấu)."}, {"q": "Quyết tâm năm nay được nhấn mạnh bằng mẫu nào?", "options": ["～こそ", "～だけ", "～ばかり", "～しか"], "answer": 0, "explain": "「今年こそは」 — ～こそ nhấn mạnh 'chính năm nay'."}, {"q": "～ばかり (câu 1) và ～ばかりに (câu 2) khác nhau thế nào?", "options": ["ばかり = nguyên nhân", "ばかりに = chỉ toàn", "ばかり = chỉ toàn làm một việc; ばかりに = chỉ vì lý do đó mà ra hậu quả xấu", "Hoàn toàn giống nhau"], "answer": 2, "explain": "Phân biệt hai mẫu dễ nhầm nhất của Unit 07."}]}, "10": {"title": "Unit 08 · 副詞 A — Trạng từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "たとえ 親（おや）に 反対（はんたい）されても、私（わたし）は 留学（りゅうがく）したい。先輩（せんぱい）の おかげで、奨学金（しょうがくきん）の 情報（じょうほう）を 知（し）る ことが できた。一度（いちど）の 失敗（しっぱい）の せいで あきらめるのは もったいない。", "questions": [{"q": "Người viết vẫn muốn du học trong trường hợp nào?", "options": ["Dù không có tiền", "Dù sức khỏe yếu", "Dù điểm thấp", "Dù cha mẹ phản đối"], "answer": 3, "explain": "「たとえ親に反対されても」 — たとえ～ても."}, {"q": "Nhờ ai mà người viết biết thông tin học bổng?", "options": ["Bạn cùng lớp", "Thầy giáo", "Tiền bối (đàn anh/chị)", "Gia đình"], "answer": 2, "explain": "「先輩のおかげで」 — ～おかげで (nhờ, tích cực)."}, {"q": "Người viết cho rằng từ bỏ vì một lần thất bại là thế nào?", "options": ["Cần thiết", "Đáng tiếc / lãng phí (もったいない)", "Đúng đắn", "Khôn ngoan"], "answer": 1, "explain": "「一度の失敗のせいであきらめるのはもったいない」 — nếu bỏ cuộc thì nguyên nhân sẽ là せいで (tiêu cực)."}, {"q": "おかげで và せいで khác nhau thế nào?", "options": ["せいで dùng cho thời tiết", "おかげで = nhờ (kết quả tốt); せいで = tại vì (kết quả xấu)", "Cả hai đều tiêu cực", "Cả hai đều tích cực"], "answer": 1, "explain": "Cặp nguyên nhân đối lập kinh điển của N3."}]}, "11": {"title": "Unit 09 · 名詞 C — Danh từ C — Đọc hiểu · Mimi kara Oboeru", "passage": "彼（かれ）が 来（こ）ない わけが ない。約束（やくそく）は 必（かなら）ず 守（まも）る 人（ひと）だからだ。電気（でんき）が 消（き）えて いる ところを 見（み）ると、もう 寝（ね）た はずだ。今夜（こんや）は 大事（だいじ）な 試合（しあい）があるので、仕事（しごと）を 休（やす）む わけには いかない。", "questions": [{"q": "Vì sao chắc chắn anh ấy sẽ đến?", "options": ["Anh ấy luôn giữ lời hứa", "Anh ấy đã gọi điện báo", "Anh ấy không bận", "Anh ấy ở rất gần"], "answer": 0, "explain": "「約束は必ず守る人だから」 nên 「来ないわけがない」."}, {"q": "Từ việc đèn tắt, người viết suy đoán điều gì?", "options": ["Chắc anh ấy đi vắng cả đêm", "Chắc anh ấy chưa về", "Chắc anh ấy đã ngủ", "Chắc mất điện"], "answer": 2, "explain": "「もう寝たはずだ」 — ～はずだ suy đoán có căn cứ."}, {"q": "Vì sao tối nay không thể nghỉ việc?", "options": ["Có trận đấu/sự kiện quan trọng (trận đấu quan trọng)", "Ngày mai là hạn chót", "Sếp không cho phép trực tiếp", "Thiếu nhân viên"], "answer": 0, "explain": "「大事な試合があるので、休むわけにはいかない」 — không thể nghỉ vì lý do nghĩa vụ/tình huống."}, {"q": "～わけがない・～はずだ・～わけにはいかない lần lượt nghĩa là gì?", "options": ["Không đời nào / chắc chắn là / không thể làm được", "Chắc chắn / không đời nào / có thể", "Không thể / chắc chắn / không đời nào", "Cả ba đều là 'chắc chắn'"], "answer": 0, "explain": "Ba mẫu suy luận của Unit 09 cần phân biệt rõ."}]}, "12": {"title": "Unit 10 · 動詞 C — Động từ C — Đọc hiểu · Mimi kara Oboeru", "passage": "子供（こども）の ころ、私（わたし）は 母（はは）に ピアノを 習（なら）わされた。許可（きょか）が ない ことには、この 部屋（へや）は 使（つか）えない。予約（よやく）を して からでないと、人気店（にんきてん）には 入（はい）れない。", "questions": [{"q": "Hồi nhỏ người viết bị mẹ bắt làm gì?", "options": ["Học vẽ", "Học bơi", "Học tiếng Anh", "Học piano"], "answer": 3, "explain": "「ピアノを習わされた」 — sai khiến bị động (Unit 10)."}, {"q": "Điều kiện để dùng phòng này là gì?", "options": ["Phải có giấy phép", "Phải có 2 người trở lên", "Phải là hội viên", "Phải đặt trước 1 tuần"], "answer": 0, "explain": "「許可がないことには使えない」 — ～ないことには."}, {"q": "Muốn vào quán nổi tiếng cần làm gì trước?", "options": ["Đặt bàn trước", "Đến sớm xếp hàng", "Mua vé", "Gọi điện xác nhận giá"], "answer": 0, "explain": "「予約をしてからでないと入れない」 — ～てからでないと."}, {"q": "Ba mẫu trong đoạn đều liên quan đến ý nào?", "options": ["Sự bắt buộc / điều kiện tiên quyết", "Sự so sánh", "Sự tình cờ", "Sự tự nguyện"], "answer": 0, "explain": "習わされた (bị bắt), ないことには (nếu không có...thì không), てからでないと (nếu không làm trước thì không) — đều là điều kiện/bắt buộc."}]}, "13": {"title": "Unit 11 · カタカナ B — Từ mượn B — Đọc hiểu · Mimi kara Oboeru", "passage": "年（とし）を 取（と）るに つれて、体力（たいりょく）が 落（お）ちて くるのは 自然（しぜん）だ。経済（けいざい）の 発展（はってん）に したがって、生活様式（せいかつようしき）も 変（か）わって きた。一方（いっぽう）で、便利（べんり）さの 裏（うら）には 新（あたら）しい 問題（もんだい）も 生（う）まれて いる。", "questions": [{"q": "Điều gì giảm dần theo tuổi tác?", "options": ["Thể lực", "Chiều cao", "Trí nhớ (không nhắc)", "Thu nhập"], "answer": 0, "explain": "「年を取るにつれて、体力が落ちてくる」 — ～につれて."}, {"q": "Điều gì thay đổi theo phát triển kinh tế?", "options": ["Lối sống", "Dân số", "Khí hậu", "Giá cả"], "answer": 0, "explain": "「経済の発展にしたがって、生活様式も変わってきた」 — ～にしたがって."}, {"q": "Mặt trái của sự tiện lợi là gì?", "options": ["Chi phí tăng", "Thời gian rảnh ít đi", "Những vấn đề mới nảy sinh", "Con người lười biếng hơn (không nói)"], "answer": 2, "explain": "「便利さの裏には新しい問題も生まれている」."}, {"q": "～につれて và ～にしたがって trong đoạn có quan hệ gì?", "options": ["Chỉ dùng cho quá khứ / chỉ dùng cho tương lai", "Một cái chỉ nguyên nhân, một cái chỉ điều kiện", "Hoàn toàn trái nghĩa", "Gần như đồng nghĩa — biến đổi song hành theo thời gian"], "answer": 3, "explain": "Cả hai đều là 'cùng với...thì...' — にしたがって trang trọng hơn một chút."}]}, "14": {"title": "Tổng hợp 3 · 料理の動詞 — Động từ nấu ăn — Đọc hiểu · Mimi kara Oboeru", "passage": "この 橋（はし）の 長（なが）さは ５０メートル、幅（はば）は １０メートルだ。彼（かれ）の 優（やさ）しさに、多（おお）くの 人（ひと）が 助（たす）けられて きた。安全（あんぜん）の 上（じょう）では、確認作業（かくにんさぎょう）を 省（はぶ）く ことは できない。", "questions": [{"q": "Chiều dài của cây cầu là bao nhiêu?", "options": ["10 mét", "50 mét", "60 mét", "40 mét"], "answer": 1, "explain": "「長さは５０メートル」 — danh từ hóa ～さ."}, {"q": "Độ rộng (幅) của cầu là bao nhiêu?", "options": ["20 mét", "5 mét", "50 mét", "10 mét"], "answer": 3, "explain": "「幅は１０メートルだ」."}, {"q": "Nhiều người đã được giúp đỡ nhờ điều gì của anh ấy?", "options": ["Sự giàu có", "Sự nổi tiếng", "Sự dịu dàng/tốt bụng", "Sức mạnh"], "answer": 2, "explain": "「彼の優しさに、多くの人が助けられてきた」."}, {"q": "Cụm 安全の上では có nghĩa là gì?", "options": ["Trong vùng an toàn", "Xét về mặt an toàn", "Ở trên cầu an toàn", "Sau khi an toàn"], "answer": 1, "explain": "～上（じょう）では = về mặt/xét về phương diện."}]}, "15": {"title": "Unit 12 · 副詞 B・連体詞・接続詞 — Trạng từ B, định ngữ, liên từ — Đọc hiểu · Mimi kara Oboeru", "passage": "彼（かれ）は 約束（やくそく）した。それでも、来（こ）なかった。そのため、会議（かいぎ）は 延期（えんき）された。要（よう）するに、準備不足（じゅんびぶそく）が 原因（げんいん）だったのである。", "questions": [{"q": "Anh ấy đã làm gì dù đã hứa?", "options": ["Gọi điện xin lỗi trước", "Vẫn không đến", "Đến muộn 1 tiếng", "Gửi người thay thế"], "answer": 1, "explain": "「それでも、来なかった」 — それでも = vậy mà."}, {"q": "Hậu quả của việc anh ấy không đến là gì?", "options": ["Cuộc họp hủy hẳn", "Cuộc họp bị hoãn", "Cuộc họp vẫn diễn ra bình thường", "Đổi trưởng nhóm"], "answer": 1, "explain": "「そのため、会議は延期された」 — そのため = vì vậy."}, {"q": "Kết luận cuối cùng về nguyên nhân là gì?", "options": ["Chuẩn bị không đủ", "Thiếu người", "Thiếu kinh phí", "Lỗi kỹ thuật"], "answer": 0, "explain": "「要するに、準備不足が原因だった」 — 要するに = tóm lại."}, {"q": "Ba liên từ それでも・そのため・要するに lần lượt chỉ quan hệ gì?", "options": ["Nhượng bộ / kết quả / tóm tắt kết luận", "Thời gian / điều kiện / kết quả", "Bổ sung / nhượng bộ / kết quả", "Kết quả / nhượng bộ / bổ sung"], "answer": 0, "explain": "Đây là nhóm liên từ văn bản của Unit 12 — chốt lại hệ thống đọc hiểu N3."}]}}};
